-- ProjectMetadata: Project overview
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS project_metadata (
  project_id                          TEXT                 PRIMARY KEY
);
ALTER TABLE project_metadata ADD COLUMN IF NOT EXISTS name TEXT;                                    -- Effortlessly Invariant Rulesbooks (ERB)
ALTER TABLE project_metadata ADD COLUMN IF NOT EXISTS purpose TEXT;                                 -- Host a catalog of independent Effortless projects (rulebook-examples/<project>/), each a self-contained rulebook that fully captures one domain and selects the subset of platform substrates it needs. The platform proves that a rulebook is a complete spec: given just the rulebook, any frontier LLM can answer any question about the domain or produce a faithful implementation in any language / platform.
ALTER TABLE project_metadata ADD COLUMN IF NOT EXISTS architecture TEXT;                            -- Catalog of N independent Effortless projects under rulebook-examples/. Each project's rulebook JSON is its own hub / durable SSoT, with input spokes (Airtable, LLM edits, admin portal) and a project-chosen subset of the platform's 15 substrates as output spokes. The platform itself is one such project (effortless-platform/) describing ERB.
ALTER TABLE project_metadata ADD COLUMN IF NOT EXISTS entry_point TEXT;                             -- ./start.sh boots the admin portal (web UI) — local dev experience for any rulebook project
ALTER TABLE project_metadata ADD COLUMN IF NOT EXISTS portal_url TEXT;                              -- http://localhost:7777 — admin portal served by run-web-portal.sh
ALTER TABLE project_metadata ADD COLUMN IF NOT EXISTS proxy_url TEXT;                               -- http://localhost:4242 — ssotme-proxy serving substrate transpilers as HTTP routes
ALTER TABLE project_metadata ADD COLUMN IF NOT EXISTS repository_root TEXT;                         -- effortlessly-invariant-rulesbooks/
