CREATE TABLE IF NOT EXISTS erb_features (
  erb_feature_id                      TEXT                 PRIMARY KEY          -- PK.
);
ALTER TABLE erb_features ADD COLUMN IF NOT EXISTS title TEXT;                                       -- Feature title.
