-- ----------------------------------------------------------------------------
-- UserStories: User stories of the repo-consistency programme (progress-report contract).
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS user_stories (
  user_story_id                       TEXT                 PRIMARY KEY          -- PK.
);
ALTER TABLE user_stories ADD COLUMN IF NOT EXISTS req_id TEXT;                                      -- Requirement code shown in the report (US-001 ...).
ALTER TABLE user_stories ADD COLUMN IF NOT EXISTS story_text TEXT;                                  -- As a <persona>, I want <capability>, so <outcome>.
ALTER TABLE user_stories ADD COLUMN IF NOT EXISTS build_phase TEXT;                                 -- FK to BuildPhases.
ALTER TABLE user_stories ADD COLUMN IF NOT EXISTS epic TEXT;                                        -- FK to ERBFeatureCategories. Read directly by the report (not inferred via Feature).
