-- ----------------------------------------------------------------------------
-- ConsistencyRules: Repo-wide consistency invariants as data. Each row is a checkable rule with a fix playbook; ConsistencyFindings rows are its violations.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS consistency_rules (
  consistency_rule_id                 TEXT                 PRIMARY KEY          -- PK.
);
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS rule_code TEXT;                              -- Short slug code of the rule.
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS severity TEXT;                               -- critical | major | minor.
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS scope TEXT;                                  -- demo (per project directory) | repo (whole repository).
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS statement TEXT;                              -- The invariant in one sentence.
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS check_mechanism TEXT;                        -- How the rule is verified (shell/jq sketch or derived-field reference).
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS fix_playbook TEXT;                           -- How to bring a violating project into conformance.
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS source_doctrine TEXT;                        -- Where the rule is stated (CLAUDE.md section or skill).
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS is_scanner_derived BOOLEAN;                  -- True when this rule's findings are re-derived by scripts/scan-project-slots.py; they close by re-running the scan, never by hand.
ALTER TABLE consistency_rules ADD COLUMN IF NOT EXISTS project TEXT;                                -- FK to ProjectMetadata.
COMMENT ON TABLE consistency_rules IS 'Repo-wide consistency invariants as data. Each row is a checkable rule with a fix playbook; ConsistencyFindings rows are its violations.';
COMMENT ON COLUMN consistency_rules.consistency_rule_id IS 'PK.';
COMMENT ON COLUMN consistency_rules.rule_code IS 'Short slug code of the rule.';
COMMENT ON COLUMN consistency_rules.severity IS 'critical | major | minor.';
COMMENT ON COLUMN consistency_rules.scope IS 'demo (per project directory) | repo (whole repository).';
COMMENT ON COLUMN consistency_rules.statement IS 'The invariant in one sentence.';
COMMENT ON COLUMN consistency_rules.check_mechanism IS 'How the rule is verified (shell/jq sketch or derived-field reference).';
COMMENT ON COLUMN consistency_rules.fix_playbook IS 'How to bring a violating project into conformance.';
COMMENT ON COLUMN consistency_rules.source_doctrine IS 'Where the rule is stated (CLAUDE.md section or skill).';
COMMENT ON COLUMN consistency_rules.is_scanner_derived IS 'True when this rule''s findings are re-derived by scripts/scan-project-slots.py; they close by re-running the scan, never by hand.';
COMMENT ON COLUMN consistency_rules.project IS 'FK to ProjectMetadata.';

-- ----------------------------------------------------------------------------
-- ConsistencyFindings: Witnessed violations of ConsistencyRules, one row per (domain, rule) occurrence. This is the sweep work queue.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS consistency_findings (
  consistency_finding_id              TEXT                 PRIMARY KEY          -- PK.
);
ALTER TABLE consistency_findings ADD COLUMN IF NOT EXISTS rule TEXT;                                -- FK to ConsistencyRules.
ALTER TABLE consistency_findings ADD COLUMN IF NOT EXISTS domain TEXT;                              -- FK to RulebookDomains; null for repo-scope findings.
ALTER TABLE consistency_findings ADD COLUMN IF NOT EXISTS detail TEXT;                              -- What exactly was observed.
ALTER TABLE consistency_findings ADD COLUMN IF NOT EXISTS status TEXT;                              -- open | fixed | accepted-exception.
ALTER TABLE consistency_findings ADD COLUMN IF NOT EXISTS detected_on DATE;                         -- ISO date the finding was witnessed.
COMMENT ON TABLE consistency_findings IS 'Witnessed violations of ConsistencyRules, one row per (domain, rule) occurrence. This is the sweep work queue.';
COMMENT ON COLUMN consistency_findings.consistency_finding_id IS 'PK.';
COMMENT ON COLUMN consistency_findings.rule IS 'FK to ConsistencyRules.';
COMMENT ON COLUMN consistency_findings.domain IS 'FK to RulebookDomains; null for repo-scope findings.';
COMMENT ON COLUMN consistency_findings.detail IS 'What exactly was observed.';
COMMENT ON COLUMN consistency_findings.status IS 'open | fixed | accepted-exception.';
COMMENT ON COLUMN consistency_findings.detected_on IS 'ISO date the finding was witnessed.';

