ALTER TABLE mobile_routes ADD COLUMN IF NOT EXISTS route_kind TEXT;                                 -- dashboard | list | detail | action | settings.
ALTER TABLE mobile_routes ADD COLUMN IF NOT EXISTS sort_order INTEGER;                              -- Order within the tab.
